/**
 * Tests for the `compress()` API — provider shapes, invariants, and a
 * golden-parity fixture suite.
 *
 * Golden-parity: the expected outputs below were generated by running the
 * Python engine (`distil.adapters.anthropic._apply_tier0`) on each fixture
 * string. If a value here ever diverges from the Python output the cross-
 * implementation conformance test (tests/test_ts_sdk_conformance.py) catches it
 * at CI time against the live Python engine.
 */
import { describe, expect, it } from "vitest";
import { compress } from "../compress.js";
import type { AnthropicMessage, OpenAIMessage } from "../types.js";

const BIG_LOG = "ERROR failed to connect to worker pool\n".repeat(50);

// ── Golden-parity fixtures ────────────────────────────────────────────────────
// Each entry: [label, input_text, expected_output_text]
// Expected outputs were derived from `_apply_tier0(text)` in Python.

const GOLDEN: Array<[string, string]> = [
  // Repetitive log — the marker form must match the Python collapse output
  ["big_log", BIG_LOG],
  // Plain JSON — minified
  ['json_obj', '{"b": 1, "a": 2}'],
  // Nested JSON
  ['json_nested', '{"outer": {"inner": [1, 2, 3], "s": "x"}}'],
  // JSON array
  ['json_array', "[1, 2, 3]"],
  // String with embedded numbers that look like exponent: must NOT be declined
  ['json_str_line1', '{"msg": "line1"}'],
  // Non-JSON — pass through
  ['plain', "just one line\n"],
  // Mixed runs
  ['mixed_runs', "x\nx\ny\nz\nz\nz\nz\n"],
  // Unicode
  ['unicode', "héllo wörld ✓\nhéllo wörld ✓\n"],
];

// Expected Tier-0 outputs for the golden corpus, produced by running
// `_apply_tier0` on each input in Python (verified 2026-10-29):
//
// mixed_runs and unicode are unchanged: the run markers cost MORE tokens than the
// short repeated lines they'd replace, so the reject-if-bigger guard fires.
const EXPECTED: Record<string, string> = {
  big_log: "ERROR failed to connect to worker pool\n<<x50>>\n",
  json_obj: '{"b":1,"a":2}',
  json_nested: '{"outer":{"inner":[1,2,3],"s":"x"}}',
  json_array: "[1,2,3]",
  json_str_line1: '{"msg":"line1"}',
  plain: "just one line\n",       // unchanged: single line, nothing to compress
  mixed_runs: "x\nx\ny\nz\nz\nz\nz\n",  // unchanged: markers cost more tokens
  unicode: "héllo wörld ✓\nhéllo wörld ✓\n",  // unchanged: same reason
};

describe("golden-parity (applyTier0 matches Python engine)", () => {
  for (const [label, input] of GOLDEN) {
    it(`${label}`, () => {
      // compress() routes through applyTier0 for string content
      const r = compress([{ role: "user", content: input }], { provider: "anthropic" });
      const got = (r.messages[0] as AnthropicMessage).content as string;
      const expected = EXPECTED[label];
      expect(got).toBe(expected);
    });
  }
});

// ── Anthropic provider ────────────────────────────────────────────────────────

describe("compress (anthropic)", () => {
  it("compresses a large repetitive tool result", () => {
    const msgs: AnthropicMessage[] = [{ role: "user", content: BIG_LOG }];
    const { receipt } = compress(msgs, { provider: "anthropic" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
    expect(receipt.savedPct).toBeGreaterThan(50);
    expect(receipt.tier).toBe("lossless");
  });

  it("never rewrites assistant turns", () => {
    const msgs: AnthropicMessage[] = [{ role: "assistant", content: BIG_LOG }];
    const { messages } = compress(msgs, { provider: "anthropic" });
    expect((messages[0] as AnthropicMessage).content).toBe(BIG_LOG);
    expect(messages[0]).toBe(msgs[0]); // identity
  });

  it("passes through identity when no compression possible", () => {
    const msgs: AnthropicMessage[] = [{ role: "user", content: "short text" }];
    const { messages } = compress(msgs, { provider: "anthropic" });
    expect(messages[0]).toBe(msgs[0]);
  });

  it("does not mutate input", () => {
    const msgs: AnthropicMessage[] = [{ role: "user", content: BIG_LOG }];
    const snapshot = JSON.stringify(msgs);
    compress(msgs, { provider: "anthropic" });
    expect(JSON.stringify(msgs)).toBe(snapshot);
  });

  it("compresses text blocks inside content arrays", () => {
    const msgs: AnthropicMessage[] = [
      {
        role: "user",
        content: [{ type: "text", text: BIG_LOG }],
      },
    ];
    const { messages, receipt } = compress(msgs, { provider: "anthropic" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
    const content = (messages[0] as AnthropicMessage).content as { type: string; text: string }[];
    expect(content[0]?.text).not.toBe(BIG_LOG);
  });

  it("leaves image blocks untouched", () => {
    const img = { type: "image" as const, source: { type: "base64", data: "abc" } };
    const msgs: AnthropicMessage[] = [{ role: "user", content: [img] }];
    const { messages } = compress(msgs, { provider: "anthropic" });
    expect((messages[0] as AnthropicMessage).content[0]).toBe(img);
  });

  it("leaves tool_use blocks untouched", () => {
    const tu = { type: "tool_use" as const, id: "x", name: "bash", input: {} };
    const msgs: AnthropicMessage[] = [{ role: "user", content: [tu] }];
    const { messages } = compress(msgs, { provider: "anthropic" });
    expect((messages[0] as AnthropicMessage).content[0]).toBe(tu);
  });

  it("compresses tool_result string content", () => {
    const msgs: AnthropicMessage[] = [
      {
        role: "user",
        content: [{ type: "tool_result", content: BIG_LOG }],
      },
    ];
    const { messages, receipt } = compress(msgs, { provider: "anthropic" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
    const block = (messages[0] as AnthropicMessage).content[0] as { type: string; content: string };
    expect(block.content).not.toBe(BIG_LOG);
  });

  it("handles empty messages array", () => {
    const { messages, receipt } = compress([], { provider: "anthropic" });
    expect(messages).toHaveLength(0);
    expect(receipt.savedPct).toBe(0);
  });

  it("throws TypeError for non-array input", () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    expect(() => compress("not an array" as any, { provider: "anthropic" })).toThrow(TypeError);
  });
});

// ── OpenAI provider ───────────────────────────────────────────────────────────

describe("compress (openai)", () => {
  it("compresses user message string content", () => {
    const msgs: OpenAIMessage[] = [{ role: "user", content: BIG_LOG }];
    const { receipt } = compress(msgs, { provider: "openai" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
  });

  it("compresses system message string content", () => {
    const msgs: OpenAIMessage[] = [{ role: "system", content: BIG_LOG }];
    const { receipt } = compress(msgs, { provider: "openai" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
  });

  it("compresses tool message string content", () => {
    const msgs: OpenAIMessage[] = [{ role: "tool", content: BIG_LOG }];
    const { receipt } = compress(msgs, { provider: "openai" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
  });

  it("never rewrites assistant turns", () => {
    const msgs: OpenAIMessage[] = [{ role: "assistant", content: BIG_LOG }];
    const { messages } = compress(msgs, { provider: "openai" });
    expect(messages[0]).toBe(msgs[0]);
  });

  it("handles null content gracefully", () => {
    const msgs: OpenAIMessage[] = [{ role: "assistant", content: null }];
    const { messages } = compress(msgs, { provider: "openai" });
    expect(messages[0]).toBe(msgs[0]);
  });

  it("compresses text parts in content arrays", () => {
    const msgs: OpenAIMessage[] = [
      {
        role: "user",
        content: [{ type: "text", text: BIG_LOG }],
      },
    ];
    const { receipt } = compress(msgs, { provider: "openai" });
    expect(receipt.tokensSaved).toBeGreaterThan(0);
  });

  it("leaves image_url parts untouched", () => {
    const img = { type: "image_url" as const, image_url: { url: "data:..." } };
    const msgs: OpenAIMessage[] = [{ role: "user", content: [img] }];
    const { messages } = compress(msgs, { provider: "openai" });
    expect((messages[0] as OpenAIMessage).content![0]).toBe(img);
  });

  it("handles empty array", () => {
    const { messages, receipt } = compress([], { provider: "openai" });
    expect(messages).toHaveLength(0);
    expect(receipt.savedPct).toBe(0);
  });
});

// ── Receipt ───────────────────────────────────────────────────────────────────

describe("receipt", () => {
  it("tokensBefore >= tokensAfter for a compressible input", () => {
    const { receipt } = compress([{ role: "user", content: BIG_LOG }], { provider: "anthropic" });
    expect(receipt.tokensBefore).toBeGreaterThanOrEqual(receipt.tokensAfter);
  });

  it("savedPct is 0 when nothing was compressed", () => {
    const { receipt } = compress([{ role: "user", content: "short" }], { provider: "anthropic" });
    expect(receipt.savedPct).toBe(0);
  });

  it("tier is always 'lossless'", () => {
    const { receipt } = compress([{ role: "user", content: BIG_LOG }], { provider: "anthropic" });
    expect(receipt.tier).toBe("lossless");
  });
});
